import{Ct as e,Q as t,at as n,it as r,jt as i,nt as a,ot as o,st as s,t as c,tt as l,yt as u}from"./chunks/framework.BXnsBMxG.js";var d=JSON.parse(`{"title":"Understanding \\"the Graph\\"","description":"","frontmatter":{},"headers":[],"relativePath":"guides/the-manual/relational-data/advanced/the-graph.md","filePath":"guides/the-manual/relational-data/advanced/the-graph.md"}`),f={name:`guides/the-manual/relational-data/advanced/the-graph.md`};function p(c,d,f,p,m,h){let g=e(`Mermaid`);return u(),r(`div`,null,[d[1]||=l(`h1`,{id:`understanding-the-graph`,tabindex:`-1`},[o(`Understanding "the Graph" `),l(`a`,{class:`header-anchor`,href:`#understanding-the-graph`,"aria-label":`Permalink to “Understanding "the Graph"”`},`​`)],-1),d[2]||=l(`p`,null,[o(`Relationship state is not stored on records. It lives in `),l(`strong`,null,`the Graph`),o(`, a relational map owned by the cache that stores one `),l(`em`,null,`edge`),o(` per `),l(`code`,null,`(resource, relationship field)`),o(` pair.`)],-1),(u(),a(t,null,{default:i(()=>[s(g,{id:`mermaid-6`,class:`mermaid`,graph:`graph%20LR%3B%0A%20%20%20%20A(user%3A1%20.friends)%20%3D%3D%20data%20%3D%3D%3E%20B(user%3A2)%0A%20%20%20%20A%20%3D%3D%20data%20%3D%3D%3E%20C(user%3A3)%0A%20%20%20%20B(user%3A2%20.friends)%20-.%20inverse%20.-%3E%20A%0A`})]),fallback:i(()=>[...d[0]||=[o(` Loading... `,-1)]]),_:1})),d[3]||=n(`<p>Each edge records:</p><ul><li><strong>remote state</strong> — the membership last confirmed by the API,</li><li><strong>local state</strong> — the membership including unsaved changes,</li><li><strong>links</strong> and <strong>meta</strong> — copied verbatim from the last relationship payload,</li><li><strong>definition</strong> — the field&#39;s kind, <code>type</code>, <code>async</code>, <code>inverse</code> and polymorphism settings, upgraded once from your schema.</li></ul><h2 id="operations-not-assignments" tabindex="-1">Operations, Not Assignments <a class="header-anchor" href="#operations-not-assignments" aria-label="Permalink to “Operations, Not Assignments”">​</a></h2><p>The Graph is driven by operations. A payload push becomes an <code>updateRelationship</code> operation that replaces remote state. A local edit becomes an <code>add</code>, <code>remove</code>, <code>replaceRelatedRecord</code>, <code>replaceRelatedRecords</code> or <code>sortRelatedRecords</code> operation against local state. Because every change is an explicit operation, the Graph can:</p><ul><li>update the <a href="./../features/inverses">inverse</a> edge in the same step,</li><li>compute a diff for saving (<code>changedRelationships</code>) and support rollback,</li><li>notify only the records and fields that actually changed.</li></ul><p><code>resource</code> and <code>collection</code> fields are handled by the same edge types as <code>belongsTo</code> and <code>hasMany</code>; the Graph converts them internally. The difference is at the edges of the system — what the field&#39;s value looks like on a record, and that remote updates never discard local changes for the new kinds.</p><h2 id="remote-vs-local-projections" tabindex="-1">Remote vs Local Projections <a class="header-anchor" href="#remote-vs-local-projections" aria-label="Permalink to “Remote vs Local Projections”">​</a></h2><p>A record reads its relationships as one of two projections of the edge:</p><table tabindex="0"><thead><tr><th>Record</th><th>Projection</th></tr></thead><tbody><tr><td>LegacyMode record</td><td>local state</td></tr><tr><td>PolarisMode immutable record</td><td>remote state</td></tr><tr><td>PolarisMode checked-out record</td><td>local state</td></tr></tbody></table><p>This is why an immutable PolarisMode record does not show a change made on its checked-out copy until the change is saved or committed, and why both copies share one source of truth.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to “Notifications”">​</a></h2><p>When an edge changes the Graph notifies the store with the resource key and field name, tagged with the channel (<code>&#39;local&#39;</code> or <code>&#39;remote&#39;</code>) that changed. Records subscribed to that channel mark the relationship document&#39;s <code>data</code>, <code>links</code> and <code>meta</code> (and, for collections, the backing array) as stale; the next read recomputes from the edge. Nothing is copied eagerly, and the document and array instances stay the same.</p><h2 id="relationship-payloads-replace-fields-upsert" tabindex="-1">Relationship Payloads Replace, Fields Upsert <a class="header-anchor" href="#relationship-payloads-replace-fields-upsert" aria-label="Permalink to “Relationship Payloads Replace, Fields Upsert”">​</a></h2><p>The Graph applies <strong>upsert</strong> semantics at the relationship level but <strong>replace</strong> semantics for each of <code>data</code>, <code>links</code> and <code>meta</code> within a relationship payload. A payload that omits <code>data</code> leaves the membership untouched; a payload with <code>data: []</code> empties it. This makes partial resource payloads safe while keeping relationship membership unambiguous. See the <a href="./../../caching/#relationships-are-cached-by-resourcekey-fieldname">caching guide</a>.</p>`,14)])}var m=c(f,[[`render`,p]]);export{d as __pageData,m as default};